INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8da4-7b3d-ba33-1c7d52395891'::uuid, '019f9df7-a2a2-7865-ab8c-df9bc214c173'::uuid, 'ABC is part of a polygon and the interior angle at A is 148°. The remaining interior angles are each 139°. Find the number of sides of the polygon.', '9', 'Let the polygon have n sides. One interior angle is 148° and the other (n − 1) interior angles are each 139°. So 148 + (n − 1) × 139 = (n − 2) × 180. Solving gives n = 9.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.964Z'::timestamptz, '2026-08-15T07:36:12.964Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8daa-7a0c-986a-9f06c4cafb82'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Expand and simplify the expression (4x - 3)(5 + 2x) - (3x - 1)^2.', '-x^2 + 20x - 16', '(4x - 3)(5 + 2x) = 20x + 8x^2 - 15 - 6x = 8x^2 + 14x - 15. (3x - 1)^2 = 9x^2 - 6x + 1. Subtracting gives: (8x^2 + 14x - 15) - (9x^2 - 6x + 1) = -x^2 + 20x - 16.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.970Z'::timestamptz, '2026-08-15T07:36:12.970Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8dcc-7c45-aed0-1fca2b78ef7b'::uuid, '019f9df7-a2a2-78da-b367-27466579928e'::uuid, 'Solve the equation 3x/(2-x) - 5/(x+4) = 3, giving your answers correct to 3 significant figures.', 'x = 1.14 or x = -4.97', '1. Combine fractions on the left-hand side: [3x(x+4) - 5(2-x)] / [(2-x)(x+4)] = 3.
2. Simplify numerator: 3x^2 + 12x - 10 + 5x = 3x^2 + 17x - 10.
3. Multiply by denominator: 3x^2 + 17x - 10 = 3(-x^2 - 2x + 8).
4. Expand and rearrange into standard quadratic form: 6x^2 + 23x - 34 = 0.
5. Use quadratic formula: x = (-23 ± √(23^2 - 4(6)(-34)))/(2(6)) = (-23 ± √1345)/12.
6. x ≈ 1.14 or x ≈ -4.97.', 'Hard', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:13.004Z'::timestamptz, '2026-08-15T07:36:13.004Z'::timestamptz) ON CONFLICT (id) DO NOTHING;